def backfill_default_business(apps, schema_editor):
    """Assign every pre-ERP row to a default business (idempotent).

    Runs only when there is data worth keeping: existing users get a
    membership (superuser=owner, staff=manager, others=operator) and
    all existing invoices/customers move under the default business,
    which also gains a current-Jalali-year fiscal year.
    """
    from datetime import date, timedelta

    Business = apps.get_model('api', 'Business')
    FiscalYear = apps.get_model('api', 'FiscalYear')
    Membership = apps.get_model('api', 'BusinessMembership')
    User = apps.get_model('auth', 'User')
    Invoice = apps.get_model('api', 'Invoice')
    Customer = apps.get_model('api', 'Customer')

    if Business.objects.exists() or not User.objects.exists():
        return
    business = Business.objects.create(
        name='کسب‌وکار پیش‌فرض', template_key='services_repair', person_type='legal',
    )
    from api.jalali import gregorian_to_jalali, jalali_to_gregorian

    today = date.today()
    jy = gregorian_to_jalali(today.year, today.month, today.day)[0]
    start = date(*jalali_to_gregorian(jy, 1, 1))
    end = date(*jalali_to_gregorian(jy + 1, 1, 1)) - timedelta(days=1)
    FiscalYear.objects.create(
        business=business, title=f'سال مالی {jy}',
        start_date=start, end_date=end, is_current=True,
    )
    Invoice.objects.filter(business__isnull=True).update(business=business)
    Customer.objects.filter(business__isnull=True).update(business=business)
    for user in User.objects.all():
        role = 'owner' if user.is_superuser else ('manager' if user.is_staff else 'operator')
        Membership.objects.get_or_create(
            user=user, business=business, defaults={'role': role, 'is_default': True},
        )



